   104→<script>
   105→import * as pdfjsLib from 'pdfjs-dist';
   106→pdfjsLib.GlobalWorkerOptions.workerSrc = '/pdf.worker.js';
   107→import { v4 as uuidv4 } from 'uuid'
   108→import { markRaw } from 'vue';
   109→
   110→export default {
   111→    props: {
   112→        file: {
   113→            type: [String, ArrayBuffer],
   114→            required: true,
   115→        },
   116→    
   117→    },
   118→    data() {
   119→        return {
   120→            fields: [],
   121→            signatureCounter: 1,
   122→            availableIds: [],
   123→            draggingField: null,
   124→            resizingField: null,
   125→            isRendering: false,
   126→            offsetX: 0,
   127→            offsetY: 0,
   128→            scrollX: 0,
   129→            scrollY: 0,
   130→            pdfPages: [],
   131→            scale: 1.5,
   132→            currentPage: 1,
   133→            pdf: null,
   134→            selectedField: null,
   135→            currentDocumentIndex: 0,
   136→            showDuplicateDialog: false,
   137→            selectedFieldToDuplicate: null,
   138→            selectedDuplicatePage: null,
   139→            availableIdsPerDoc: {},
   140→        };
   141→    },
   142→    watch: {
   143→        file: {
   144→            immediate: true,
   145→            handler(newFile) {
   146→                if (newFile) {
   147→                    this.loadPDF(newFile);
   148→                }
   149→            },
   150→        },
   151→        fields: {
   152→            handler(newFields) {
   153→                this.$emit('update-fields', newFields);
   154→            },
   155→            deep: true,
   156→        },
   157→    },
   158→ 
   159→    methods: {
   160→       async loadPDF(file) {
   161→            try {
   162→                 const fileReader = new FileReader();
   163→                fileReader.onload = async (e) => {
   164→                    const pdfData = new Uint8Array(e.target.result);
   165→                    const loadingTask = pdfjsLib.getDocument({ data: pdfData });
   166→                    this.pdf = markRaw(await loadingTask.promise);
   167→                    this.pdfPages = Array.from({ length: this.pdf.numPages }, (_, i) => i + 1);
   168→                    this.$nextTick(() => {
   169→                        this.renderPage(this.currentPage);
   170→                    });
   171→                };
   172→                fileReader.readAsArrayBuffer(file);
   173→
   174→            } catch (error) {
   175→                console.error('Error loading PDF:', error);
   176→            }
   177→        },
   178→
   179→        async renderPage(pageNumber) {
   180→            try {
   181→
   182→                if (!this.$refs.pdfCanvas) {
   183→                    console.error('PDF canvas reference not found.');
   184→                    return;
   185→                }
   186→
   187→                const canvas = this.$refs.pdfCanvas;
   188→
   189→                const page = await this.pdf.getPage(pageNumber);
   190→                const viewport = page.getViewport({ scale: this.scale });
   191→
   192→                canvas.width = viewport.width;
   193→                canvas.height = viewport.height;
   194→
   195→                const context = canvas.getContext('2d');
   196→                const renderTask = page.render({ canvasContext: context, viewport });
   197→                this.renderingTask = renderTask;
   198→
   199→                await renderTask.promise;
   200→            } catch (error) {
   201→                console.error('Error rendering page:', error);
   202→            }
   203→            
   204→        },
   205→
   206→        addSignatureField() {
   207→            const initialTop = 20;
   208→            const initialLeft = 20;
   209→            const fieldId = this.availableIds.length > 0 
   210→                ? this.availableIds.shift()
   211→                : this.signatureCounter++; 
   212→          
   213→            const newField = {
   214→                id: fieldId,
   215→                name: `[$FIRMA${fieldId}]`,
   216→                type: 'signature',
   217→                top: initialTop,
   218→                left: initialLeft,
   219→                width: 200,
   220→                height: 100,
   221→                pageNumber: this.currentPage,
   222→            };
   223→
   224→            this.fields.push(newField);
   225→        },
   226→
   227→        openDuplicateDialog(field) {
   228→            this.selectedFieldToDuplicate = field;
   229→            this.selectedDuplicatePage = this.currentPage[this.currentDocumentIndex];
   230→            this.showDuplicateDialog = true;
   231→        },
   232→
   233→        confirmDuplicateField() {
   234→            if (!this.selectedFieldToDuplicate || !this.selectedDuplicatePage) return;
   235→
   236→            const original = this.selectedFieldToDuplicate;
   237→            const newField = {
   238→                ...original,
   239→                id: `${original.fileId}-${uuidv4()}`,
   240→                instanceId: `${original.fileId}-${uuidv4()}`,
   241→                pageNumber: this.selectedDuplicatePage,
   242→                top: original.top + 0.05, 
   243→                left: original.left + 0.05,
   244→            };
   245→
   246→            newField.top = Math.min(newField.top, 0.9);
   247→            newField.left = Math.min(newField.left, 0.9);
   248→
   249→            this.fields.push(newField);
   250→            this.showDuplicateDialog = false;
   251→        },
   252→
   253→        duplicateField(field, targetPage) {
   254→            if (!this.selectedFieldToDuplicate || !this.selectedDuplicatePage) return;
   255→
   256→            const originalField = this.selectedFieldToDuplicate;
   257→
   258→            const uniqueId = `${originalField.fileId}-${uuidv4()}`;
   259→
   260→
   261→            const canvas = this.$refs.pdfCanvas;
   262→            const canvasRect = canvas.getBoundingClientRect();
   263→
   264→            let newTop = originalField.top + canvasRect.height / 4; 
   265→            let newLeft = originalField.left;
   266→
   267→            const duplicatedField = {
   268→                ...originalField,
   269→                id: uniqueId,
   270→                instanceId: uniqueId,
   271→                pageNumber: this.selectedDuplicatePage,
   272→                left: newLeft,
   273→                top: newTop,
   274→            };
   275→
   276→            this.fields.push(duplicatedField);
   277→            this.showDuplicateDialog = false;
   278→        },
   279→
   280→        deleteField(fieldId) {
   281→            this.fields = this.fields.filter(field => field.id !== fieldId);
   282→            this.availableIds.push(fieldId)
   283→            this.availableIds.sort((a, b) => a - b);
   284→        },
   285→
   286→        startDrag(event, field) {
   287→            event.preventDefault();
   288→            this.draggingField = field;
   289→            const containerRect = this.$refs.pdfContainerMass.getBoundingClientRect();
   290→            const scale = this.scale;
   291→            this.offsetX = event.clientX - (field.left * scale + containerRect.left - this.$refs.pdfContainerMass.scrollLeft);
   292→            this.offsetY = event.clientY - (field.top * scale + containerRect.top - this.$refs.pdfContainerMass.scrollTop);
   293→            document.addEventListener('mousemove', this.onDrag);
   294→            document.addEventListener('mouseup', this.stopDrag);
   295→        },
   296→
   297→        onDrag(event) {
   298→            if (this.draggingField) {
   299→                const containerRect = this.$refs.pdfContainerMass.getBoundingClientRect();
   300→                const scale = this.scale;
   301→                this.draggingField.left = (event.clientX - this.offsetX - containerRect.left + this.$refs.pdfContainerMass.scrollLeft) / scale;
   302→                this.draggingField.top = (event.clientY - this.offsetY - containerRect.top + this.$refs.pdfContainerMass.scrollTop) / scale;
   303→            }
   304→        },
   305→
   306→        stopDrag() {
   307→            document.removeEventListener('mousemove', this.onDrag);
   308→            document.removeEventListener('mouseup', this.stopDrag);
   309→            this.draggingField = null;
   310→            this.updateFieldPositions();
   311→        },
   312→        
   313→        startResize(event, field) {
   314→            event.stopPropagation();
   315→            this.resizingField = field;
   316→            document.addEventListener('mousemove', this.onResize);
   317→            document.addEventListener('mouseup', this.stopResize);
   318→        },
   319→
   320→        onResize(event) {
   321→            if (this.resizingField) {
   322→                const containerRect = this.$refs.pdfContainerMass.getBoundingClientRect();
   323→                const scale = this.scale;
   324→
   325→                let newWidth = (event.clientX - containerRect.left + this.$refs.pdfContainerMass.scrollLeft - this.resizingField.left * scale) / scale;
   326→                let newHeight = (event.clientY - containerRect.top + this.$refs.pdfContainerMass.scrollTop - this.resizingField.top * scale) / scale;
   327→
   328→                const minWidth = 150;
   329→                const minHeight = 100;
   330→                const maxWidth = 250;
   331→                const maxHeight = 180;
   332→
   333→                this.resizingField.width = Math.max(minWidth, Math.min(newWidth, maxWidth));
   334→                this.resizingField.height = Math.max(minHeight, Math.min(newHeight, maxHeight));
   335→            }
   336→        },
   337→
   338→        stopResize() {
   339→            document.removeEventListener('mousemove', this.onResize);
   340→            document.removeEventListener('mouseup', this.stopResize);
   341→            this.resizingField = null;
   342→            this.updateFieldPositions();
   343→        },
   344→
   345→        updateFieldPositions() {
   346→            console.log('Updated field positions:', this.fields);
   347→        },
   348→
   349→        onScroll() {
   350→            this.scrollX = this.$refs.pdfContainerMass.scrollLeft;
   351→            this.scrollY = this.$refs.pdfContainerMass.scrollTop;
   352→        },
   353→
   354→        nextPage() {
   355→            if (this.currentPage < this.pdfPages.length) {
   356→                this.currentPage++;
   357→                this.renderPage(this.currentPage);
   358→            }
   359→        },
   360→
   361→        prevPage() {
   362→            if (this.currentPage > 1) {
   363→                this.currentPage--;
   364→                this.renderPage(this.currentPage);
   365→            }
   366→        },
   367→
   368→        selectField(field) {
   369→            this.selectedField = field;
   370→        },
   371→     
   372→    },
   373→};
