   261→import { v4 as uuidv4 } from 'uuid'
   262→import { markRaw } from 'vue';
   263→
   264→export default {
   265→  props: {
   266→    files: {
   267→      type: Array,
   268→      required: true,
   269→    },
   270→  },
   271→  data() {
   272→    return {
   273→      pdfCanvasWidth: 0,
   274→      pdfCanvasHeight: 0,
   275→      originalPdfWidth: 0,
   276→      originalPdfHeight: 0,
   277→      fields: [],
   278→      isRendering: false,
   279→      signatureCounters: {},
   280→      renderingTask: null,
   281→      loadingPDFs: false,
   282→      availableIds: [],
   283→      draggingField: null,
   284→      resizingField: null,
   285→      offsetX: 0,
   286→      offsetY: 0,
   287→      scrollX: 0,
   288→      scrollY: 0,
   289→      scale: 1.5,
   290→      currentScale: 1,
   291→      initialScale: 1,
   292→      pdfs: [],
   293→      pdfPages: {},
   294→      scales: {},
   295→      currentPage: {},
   296→      pdf: null,
   297→      selectedField: null,
   298→      currentDocumentIndex: 0,
   299→      showDuplicateDialog: false,
   300→      selectedFieldToDuplicate: null,
   301→      selectedDuplicatePage: null,
   302→      availableIdsPerDoc: {},
