   347→        this.enforceMinDataSize();
   348→      }
   349→    },
   350→
   351→    'editingField.includeDocumentInfo'(newValue) {
   352→      if (newValue === true) {
   353→        this.enforceMinDataSize();
   354→      }
   355→    },
   356→
   357→    fields: {
   358→      deep: true,
   359→      handler(newFields) {
   360→        const groupedFields = {};
   361→
   362→        newFields.forEach(field => {
   363→          if (field.fileId !== undefined && field.fileId !== null) {
   364→            if (!groupedFields[field.fileId]) {
   365→              groupedFields[field.fileId] = [];
   366→            }
   367→            groupedFields[field.fileId].push(field);
   368→          }
   369→        });
   370→
   371→        Object.keys(groupedFields).forEach(fileId => {
